const listPromotionStages = `-- name: ListPromotionStages :many
SELECT id, integration, cluster_name, project, name, kubernetes_uid, resource_version, application, environment, repository_name, repository_url, target_branch, source_paths, freight_json, successful_render_acknowledgement, first_observed_at, last_observed_at, archived_at
FROM promotion_stages
ORDER BY integration, project, name
`

func (q *Queries) ListPromotionStages(ctx context.Context) ([]PromotionStage, error) {
	rows, err := q.db.Query(ctx, listPromotionStages)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PromotionStage
	for rows.Next() {
		var i PromotionStage
		if err := rows.Scan(
			&i.ID,
			&i.Integration,
			&i.ClusterName,
			&i.Project,
			&i.Name,
			&i.KubernetesUid,
			&i.ResourceVersion,
			&i.Application,
			&i.Environment,
			&i.RepositoryName,
			&i.RepositoryUrl,
			&i.TargetBranch,
			&i.SourcePaths,
			&i.FreightJson,
			&i.SuccessfulRenderAcknowledgement,
			&i.FirstObservedAt,
			&i.LastObservedAt,
			&i.ArchivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

